import React from "react";

const Result = ({ style, occasion }) => {
  const outfitSuggestions = {
    Classic: {
      Work: "Tailored blazer, structured vest, wide-leg trousers, and minimal accessories.",
      Party: "Flowing satin midi dress with a tie-neck, paired with a structured bag, refined watch, and elegant slingback heels.",
      Casual: "Wide-leg trousers, a structured peplum top, a chain-strap bag, two-tone ballet flats, and minimal accessories.",
      Vacation: "Midi dress with ruffled detailing, complemented by a sun hat, sunglasses, a tote bag, and flat sandals.",
    },
    Boho: {
      Work: "Satin wrap top and wide-leg trousers, combined with pointed-toe heels, a structured belt, and sunglasses.",
      Party: "Floral halter-neck dress, high heels, a structured bag, and delicate jewelry.",
      Casual: "Crop top with a tiered maxi skirt, a cream cardigan, black flats, a two-toned shoulder bag, and glasses.",
      Vacation: "Tiered, embroidered midi dress, tote bag, and flat style sandals.",
    },
    Chic: {
      Work: "Short-sleeved shirt and wide-leg trousers paired with a belt, gold jewelry, sunglasses, a structured bag, a watch, and nude heels.",
      Party: "Ruffled camisole top, black wide-leg trousers, high-heeled sandals, and a structured handbag.",
      Casual: "Puff-sleeve top with tie details, wide-leg jeans, heels, a tweed bag, and gold accessories.",
      Vacation: "Floral midi dress, straw tote bag, and white block-heeled sandals.",
    },
    Streetwear: {
      Work: "Trench coat, wide-leg jeans, sneakers, and a structured bag with gold accessories.",
      Party: "Crop top with wide-leg cargo jeans, matching bag, tinted sunglasses, and checkered slip-on sneakers.",
      Casual: "Lavender shirt and tank, wide-leg jeans, crisp white sneakers, and a structured top-handle bag.",
      Vacation: "An oversized, jersey-style top, denim shorts, comfortable sneakers, a shoulder bag, and sunglasses.",
    },
  };

  const outfit =
    style && occasion ? outfitSuggestions[style]?.[occasion] : null;

  return (
    <div style={{ padding: "20px", maxWidth: "600px", margin: "0 auto" }}>
      <h2>🎀 Your Outfit Suggestion</h2>

      {outfit ? (
        <>
          <p style={{ fontSize: "18px", lineHeight: "1.6" }}>
            <strong>Style:</strong> {style}
            <br />
            <strong>Occasion:</strong> {occasion}
            <br />
            <br />
            <strong>Suggested Outfit:</strong> {outfit}
          </p>
        </>
      ) : (
        <p>Please complete the quiz to get your outfit suggestion!</p>
      )}
    </div>
  );
};

export default Result;
